target.css:
:root {
  --ink: #123047;
  --muted: #5f7888;
  --water: #dff5f3;
  --line: #a9d9d5;
  --accent: #ed7c4d;
  --paper: #ffffff;
}

.lane-pass {
  width: 460px;
  box-sizing: border-box;
  padding: 16px;
  border: 2px solid var(--ink);
  border-radius: 16px;
  background: var(--paper);
  color: var(--ink);
}

.pass-header {
  display: flex;
  align-items: center;
  gap: 10px;
}

.pool-mark {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border-radius: 12px;
  background: var(--water);
  font-size: 22px;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
}

h1 {
  margin: 0;
  font-size: 20px;
  line-height: 1.1;
}

.lane-number {
  margin-left: auto;
  color: var(--accent);
  font-size: 26px;
  font-weight: 800;
}

.pass-details {
  display: flex;
  gap: 10px;
  margin: 14px 0;
}

.pass-details p {
  flex: 1;
  margin: 0;
  padding: 10px;
  border-radius: 10px;
  background: var(--water);
}

.pass-details strong,
.pass-details span {
  display: block;
}

.pass-details strong {
  font-size: 14px;
}

.pass-details span {
  margin-top: 3px;
  color: var(--muted);
  font-size: 12px;
}

.pass-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 12px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.7px;
}

button {
  padding: 7px 10px;
  border: 0;
  border-radius: 8px;
  background: var(--ink);
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
}

